42	// Percent-based arithmetic (× 110 ÷ 100) rather than a float rate (× 1.1):
43	// it keeps intermediate values integral and avoids binary floating-point
44	// error — 100 * 1.1 is 110.00000000000001, but (100 * 110) / 100 is exact.
45	const ONE_HUNDRED_PERCENT = 100;
46	const FIRST_INSURANCE_PERCENT_OF_BASE = 110;
47	const ADMIN_FEE = 5;
48	
49	const applyPercent = (amount: number, percent: number): number =>
50	  (amount * percent) / ONE_HUNDRED_PERCENT;
51	
52	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
53	
54	const totalBasePremium = (items: Item[]): number =>
55	  items.reduce((total, item) => total + basePremiumOf(item), 0);
56	
57	const quote = (step: QuoteStep): QuoteResult => {
58	  const basePremium = totalBasePremium(step.items);
59	  const premiumAfterFirstInsurance = applyPercent(
60	    basePremium,
61	    FIRST_INSURANCE_PERCENT_OF_BASE,
62	  );
63	  return { premium: Math.ceil(premiumAfterFirstInsurance) + ADMIN_FEE };
64	};
65	
66	export const runScenario = (scenario: Scenario): ScenarioResult => ({
67	  results: scenario.steps.map(quote),
68	});
